    def concurrent_producer():\\n        mapping = {'briefRef':'brief', 'evalRef':'eval', 'responsibilityPlanRef':'responsibilityPlan', 'profileRef':'profile', 'monitoringPolicyRef':'monitoringPolicy', 'capacitySnapshotRef':'capacitySnapshot', 'budgetSnapshotRef':'budgetSnapshot', 'logicRef':'logic', 'agentBindingRef':'agentBinding'}\\n        request = PreparePriceResearchBatchRequest(batchId='price-batch-2', skillRefs=first_prepared.skill_refs, items=first_prepared.items, **{k:first_prepared.exact_refs[v] for k,v in mapping.items()})\\n        with psycopg.connect(user='postgres', **args) as c: now = c.execute('SELECT transaction_timestamp() AS now').fetchone()['now']\\n        service = EcommerceWorkshopPriceResearchService(own_store)\\n        prepared = service.prepare_batch(SCOPE, request, 'fixture-operator', now=now)\\n        frozen = service.freeze_batch(SCOPE, prepared.batch_id, FreezePriceResearchBatchRequest(expectedVersion=prepared.version, expectedContentHash=prepared.content_hash, exactRefs=prepared.exact_refs), 'fixture-operator', now=now)\\n        seed(prepared); seed(frozen)\\n    @contextlib.contextmanager\\n    def connection(scope):\\n        assert scope == SCOPE\\n        with psycopg.connect(user='fixture_reader', **args) as c:\\n            c.read_only = True; c.isolation_level = IsolationLevel.REPEATABLE_READ\\n            c.execute('SET LOCAL ROLE aos_runtime')\\n            c.execute(\\\"SELECT set_config('aos.org_id',%s,true),set_config('aos.project_id',%s,true)\\\", scope.key)\\n            observations.append(dict(c.execute(\\\"SELECT current_user AS role,current_setting('transaction_read_only') AS readonly,current_setting('transaction_isolation') AS isolation\\\").fetchone()))\\n            class Probe:\\n                read_only=c.read_only; autocommit=c.autocommit; isolation_level=c.isolation_level\\n                def execute(self, statement, params=()):\\n                    result = c.execute(statement, params)\\n                    if 'transaction_timestamp() AS cutoff' in statement and not injected[0]:\\n                        injected[0]=True; concurrent_producer()\\n                    return result\\n            yield Probe()\\n    reader = PriceResearchReadonlyReader(connect_factory=connection)\\n    first, second = reader.read(SCOPE), reader.read(SCOPE)\\n    assert first.latest_batch.batch_id == 'price-batch-1' and second.latest_batch.batch_id == 'price-batch-2'\\n    assert first.latest_batch.lifecycle == second.latest_batch.lifecycle == 'frozen'\\n    assert not first.allowed_commands and not second.allowed_commands\\n    with psycopg.connect(user='fixture_reader', **args) as c:\\n        c.read_only=True; c.isolation_level=IsolationLevel.REPEATABLE_READ\\n        c.execute('SET LOCAL ROLE aos_runtime')\\n        c.execute(\\\"SELECT set_config('aos.org_id',%s,true),set_config('aos.project_id',%s,true)\\\", SCOPE.key)\\n        assert c.execute(f'SELECT count(*) AS n FROM {TABLE}').fetchone()['n'] == 4\\n        try: c.execute(f'INSERT INTO {TABLE} SELECT * FROM {TABLE}')\\n        except psycopg.Error as error: state=error.sqlstate; c.rollback()\\n        else: raise AssertionError('native write not denied')\\n    assert state == '25006'\\n    original = second.latest_batch.model_dump(mode='json', by_alias=True)\\n    def change_latest(payload):\\n        with psycopg.connect(user='postgres', **args) as c:\\n            c.execute(f'UPDATE {TABLE} SET authority_data=%s::jsonb WHERE org_id=%s AND project_id=%s AND batch_id=%s AND revision=2', (json.dumps(payload), *SCOPE.key, 'price-batch-2'))\\n    change_latest({**original, 'createdBy': 'x'*(MAX_ROW_BYTES+1)})\\n    try: reader.read(SCOPE)\\n    except PriceResearchReadonlyError as error: oversize_code=error.code\\n    else: raise AssertionError('oversize payload exposed')\\n    assert oversize_code == 'PRICE_RESEARCH_READ_LIMIT_EXCEEDED'\\n    change_latest({**original, 'createdBy':'fixture@example.invalid'})\\n    try: reader.read(SCOPE)\\n    except PriceResearchReadonlyError as error: privacy_code=error.code\\n    else: raise AssertionError('private actor exposed')\\n    assert privacy_code == 'PRICE_RESEARCH_READ_PRIVACY_UNAVAILABLE'\\n    save('native-r1-result.json', dict(containerId=cid, fixtureOnlyNotOriginalSchema=True, exactW6DdlSha=hashlib.sha256(source.encode()).hexdigest(), sourceSha=hashlib.sha256((R/'services/aos-api/aos_api/ecommerce_price_research_readonly.py').read_bytes()).hexdigest(), originalProducerUsed=True, originalVolumeTouched=False, realUserApproval=False, snapshotBatchIds=[first.latest_batch.batch_id,second.latest_batch.batch_id], nonemptyFrozenWithPreparedAncestor=True, observations=observations, foreignRowsHiddenWithoutWhere=True, writeDeniedSqlstate=state, oversizeSqlCaseError=oversize_code, privacyError=privacy_code, commandsEmpty=True))\\n    print(json.dumps(dict(snapshot=['price-batch-1','price-batch-2'], writeDenied=state, oversize=oversize_code, privacy=privacy_code, originalVolumeTouched=False)))\\nfinally:\\n    owned = json.loads(docker('inspect', NAME).stdout)[0]\\n    assert owned['Id'] == cid and owned['Config']['Labels']['aos.owner'] == OWNER\\n    assert docker('stop', NAME).returncode == 0\\n    after = json.loads(docker('inspect', NAME).stdout)[0]\\n    assert after['Id'] == cid and not after['State']['Running']\\n    save('native-r1-stopped.json', dict(containerId=cid, stopped=True, originalVolumeTouched=False))\\n\\n\\nORIGINAL producer and contribution price_research.py lines458-532\\n        item = MonitoringPolicyRevision(tenant=self._tenant(scope), **payload, contentHash=canonical_hash(payload), createdBy=actor, createdAt=at)\\n        return self.store.append_policy(scope, item)\\n\\n    def prepare_batch(self, scope: TenantScope, request: PreparePriceResearchBatchRequest, actor: str, *, now: datetime | None = None) -> PriceResearchBatchRevision:\\n        at = now or datetime.now(UTC)\\n        self.store.require_profile(scope, request.profile_ref)\\n        self.store.require_policy(scope, request.monitoring_policy_ref)\\n        counts = {item.value: 0 for item in PriceBatchDisposition}\\n        for item in request.items:\\n            observation = self.store.require_observation(scope, item.observation_ref)\\n            match_observation = self.store.require_match_observation(scope, item.match_observation_ref)\\n            decision = self.store.require_match_decision(scope, item.match_decision_ref)\\n            if match_observation.observation_ref != item.observation_ref or match_observation.sku_ref != item.sku_ref or decision.match_observation_ref != item.match_observation_ref:\\n                raise PriceResearchBlocked(\\\"PRICE_BATCH_MATCH_LINEAGE_DRIFTED\\\")\\n            required = {PriceBatchDisposition.ELIGIBLE: \\\"confirmed\\\", PriceBatchDisposition.EXCLUDED: \\\"rejected\\\", PriceBatchDisposition.NEEDS_REVIEW: \\\"needs_review\\\", PriceBatchDisposition.UNKNOWN: \\\"needs_review\\\", PriceBatchDisposition.DEDUPLICATED: \\\"confirmed\\\"}[item.disposition]\\n            if decision.disposition != required or (item.disposition is PriceBatchDisposition.ELIGIBLE and observation.comparability is not PriceComparability.COMPARABLE):\\n                raise PriceResearchBlocked(\\\"PRICE_BATCH_DISPOSITION_DRIFTED\\\")\\n            counts[item.disposition.value] += 1\\n        exact_refs = {\\n            \\\"brief\\\": request.brief_ref, \\\"eval\\\": request.eval_ref, \\\"responsibilityPlan\\\": request.responsibility_plan_ref,\\n            \\\"profile\\\": request.profile_ref, \\\"monitoringPolicy\\\": request.monitoring_policy_ref,\\n            \\\"capacitySnapshot\\\": request.capacity_snapshot_ref, \\\"budgetSnapshot\\\": request.budget_snapshot_ref,\\n            \\\"logic\\\": request.logic_ref, \\\"agentBinding\\\": request.agent_binding_ref,\\n        }\\n        payload = request.model_dump(mode=\\\"json\\\", by_alias=True)\\n        item_hashes = [canonical_hash(value.model_dump(mode=\\\"json\\\", by_alias=True)) for value in request.items]\\n        content_hash = canonical_hash({**payload, \\\"itemHashes\\\": item_hashes})\\n        existing = self.store.latest_batch_or_none_by_id(scope, request.batch_id)\\n        if existing is not None:\\n            if existing.lifecycle == \\\"prepared\\\" and existing.content_hash == content_hash:\\n                return existing\\n            raise PriceResearchConflict(\\\"PRICE_BATCH_IDEMPOTENCY_CONFLICT\\\")\\n        item = PriceResearchBatchRevision(\\n            tenant=self._tenant(scope), batchId=request.batch_id, revision=1, version=1, lifecycle=\\\"prepared\\\",\\n            exactRefs=exact_refs, skillRefs=request.skill_refs, items=request.items, itemHashes=item_hashes,\\n            ledger=PriceResearchBatchLedger(input=len(request.items), **counts), contentHash=content_hash, createdBy=actor, createdAt=at,\\n        )\\n        return self.store.append_batch(scope, item)\\n\\n    def freeze_batch(self, scope: TenantScope, batch_id: str, request: FreezePriceResearchBatchRequest, actor: str, *, now: datetime | None = None) -> PriceResearchBatchRevision:\\n        at = now or datetime.now(UTC)\\n        current = self.store.latest_batch(scope, batch_id)\\n        if current.lifecycle == \\\"frozen\\\" and current.prior_content_hash == request.expected_content_hash:\\n            return current\\n        if current.version != request.expected_version or current.content_hash != request.expected_content_hash:\\n            raise PriceResearchConflict(\\\"PRICE_BATCH_EXPECTED_VERSION_OR_HASH_DRIFTED\\\")\\n        expected = {key: value.model_dump(mode=\\\"json\\\", by_alias=True) for key, value in current.exact_refs.items()}\\n        actual = {key: value.model_dump(mode=\\\"json\\\", by_alias=True) for key, value in request.exact_refs.items()}\\n        if actual != expected or current.lifecycle != \\\"prepared\\\":\\n            raise PriceResearchBlocked(\\\"PRICE_BATCH_EXACT_REFS_OR_LIFECYCLE_DRIFTED\\\")\\n        payload = current.model_dump(mode=\\\"json\\\", by_alias=True)\\n        payload.update({\\\"revision\\\": current.revision + 1, \\\"version\\\": current.version + 1, \\\"lifecycle\\\": \\\"frozen\\\", \\\"priorContentHash\\\": current.content_hash, \\\"contentHash\\\": canonical_hash({\\\"prior\\\": current.content_hash, \\\"exactRefs\\\": actual, \\\"lifecycle\\\": \\\"frozen\\\"}), \\\"createdBy\\\": actor, \\\"createdAt\\\": at})\\n        return self.store.append_batch(scope, PriceResearchBatchRevision.model_validate(payload))\\n\\n    def contribution_view(self, scope: TenantScope, *, now: datetime | None = None) -> PriceResearchContributionView:\\n        at = now or datetime.now(UTC)\\n        try:\\n            latest = self.store.latest_batch_or_none(scope)\\n        except PriceResearchBlocked as exc:\\n            if str(exc) != \\\"PRICE_RESEARCH_AUTHORITY_UNAVAILABLE\\\":\\n                raise\\n            return PriceResearchContributionView(tenant=self._tenant(scope), evaluatedAt=at, blockers=[\\\"PRICE_RESEARCH_AUTHORITY_UNAVAILABLE\\\", \\\"PRICE_RESEARCH_BATCH_NOT_AVAILABLE\\\"])\\n        blockers = [] if latest else [\\\"PRICE_RESEARCH_BATCH_NOT_AVAILABLE\\\"]\\n        if latest and latest.lifecycle != \\\"frozen\\\":\\n            blockers.append(\\\"PRICE_RESEARCH_BATCH_NOT_FROZEN\\\")\\n        return PriceResearchContributionView(\\n            tenant=self._tenant(scope), evaluatedAt=at, atomicSkillRefs=latest.skill_refs if latest else [],\\n            logicRef=latest.exact_refs.get(\\\"logic\\\") if latest else None, latestBatch=latest, blockers=blockers,\\n        )\\n\\n\\n__all__ = [name for name in globals() if name.startswith((\\\"Price\\\", \\\"Product\\\", \\\"Monitoring\\\", \\\"Prepare\\\", \\\"Freeze\\\", \\\"Normalize\\\", \\\"Create\\\", \\\"Decide\\\")) or name in {\\\"EcommerceWorkshopPriceResearchService\\\", \\\"canonical_hash\\\", \\\"PRICE_RESEARCH_SCHEMA_VERSION\\\", \\\"PR